package main
import("errors"; "fmt"; "time"; j "github.com/pion/interceptor/pkg/jitterbuffer")
func main(){cfg:=j.RedundantConfig{OutputSSRC:333,PayloadType:96,Paths:[2]j.RedundantPath{{SSRC:11,SequenceOffset:7,RTT:time.Millisecond},{SSRC:22,SequenceOffset:99,RTT:2*time.Millisecond}},Window:8,Hold:time.Millisecond,Retry:time.Millisecond,Now:func()time.Time{return time.Unix(0,0)}}; b,e:=j.NewRedundant(cfg);if e!=nil||b==nil{panic("valid redundant constructor")};b.Clear(true);p,e:=b.Pop();if p!=nil||!errors.Is(e,j.ErrRedundantPending){panic("empty redundant queue")};f,e:=j.NewInterceptor(j.WithRedundant(cfg));if e!=nil{panic(e)};i,e:=f.NewInterceptor("probe");if e!=nil||i==nil{panic("redundant receiver constructor")};if e=i.Close();e!=nil{panic(e)};fmt.Println("redundant API consumer: ok")}
